script:
(function () {
  'use strict';
  // Broad-portfolio asset allocation across nine asset classes. Returns, volatilities and the
  // correlation are hypothetical assumptions the user controls; nothing here is a forecast.
  //   weights: current mix = value / total; target mix = target %
  //   hypothetical return R = sum(w_i x r_i)
  //   volatility with one average correlation rho between every pair of classes:
  //     sigma_p^2 = (1 - rho) x sum(w_i^2 sigma_i^2) + rho x (sum(w_i sigma_i))^2
  //   diversification effect = sum(w_i sigma_i) - sigma_p (zero when rho = 1)
  //   one-year typical range = total x (R -/+ sigma_p); about two years in three fall inside it
  //   if returns are roughly normal, about 19 in 20 inside R -/+ 2 sigma_p
  //   rebalance: target $ = target % x (total + new cash); trade = target $ - current $
  // Checked in Node (aq5/tests/ab.test.js): two classes 60/40 with sigma 16% and 5% at rho = 0.3:
  // sqrt(0.36 x 0.0256 + 0.16 x 0.0025 + 2 x 0.3 x 0.6 x 0.4 x 0.16 x 0.05) = 10.377%, same as the
  // formula above; a three-class mix matches the full pairwise covariance sum; rho = 1 gives the
  // weighted average 11.6%; rho = 0 gives sqrt(sum w^2 s^2);
  // default target mix return 6.115%, volatility 9.46%; trades net to the new cash; a one-class
  // portfolio returns that class's own figures.

  var KEYS = ['Ulc', 'Usm', 'Int', 'Emk', 'Bnd', 'Tip', 'Rea', 'Csh', 'Oth'];
  var NAMES = {
    Ulc: 'US large-cap stocks', Usm: 'US small and mid-cap stocks', Int: 'International developed stocks',
    Emk: 'Emerging-market stocks', Bnd: 'US investment-grade bonds', Tip: 'Inflation-protected and other bonds',
    Rea: 'Real estate', Csh: 'Cash', Oth: 'Other (commodities, alternatives)'
  };
  var GROUPS = { Ulc: 'Stocks', Usm: 'Stocks', Int: 'Stocks', Emk: 'Stocks', Bnd: 'Bonds', Tip: 'Bonds',
                 Rea: 'Real estate', Csh: 'Cash', Oth: 'Other' };
  var GROUP_ORDER = ['Stocks', 'Bonds', 'Real estate', 'Cash', 'Other'];

  // --- calc start
  function sum(a) { return a.reduce(function (s, x) { return s + x; }, 0); }
  function mixReturn(w, r) { return sum(w.map(function (x, i) { return x * r[i]; })); }
  function mixVol(w, s, rho) {
    var lin = sum(w.map(function (x, i) { return x * s[i]; }));
    var sq = sum(w.map(function (x, i) { return x * x * s[i] * s[i]; }));
    return Math.sqrt(Math.max(0, (1 - rho) * sq + rho * lin * lin));
  }
  function weightedVol(w, s) { return sum(w.map(function (x, i) { return x * s[i]; })); }
  function trades(current, targetW, cash) {
    var total = sum(current) + cash;
    return current.map(function (v, i) { return targetW[i] * total - v; });
  }
  // --- calc end

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var OUTPUTS = ['abTotal', 'abTgtRet', 'abCurRet', 'abTgtVol', 'abCurVol', 'abTgtDiv', 'abCurDiv',
                 'abRange1', 'abRange2', 'abMoved', 'abOffBand'];

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function pct(x) { return (x * 100).toFixed(2).replace('-', '−') + '%'; }
  function signed(x) { return Math.abs(x) < 0.5 ? '$0' : (x > 0 ? 'Buy ' : 'Sell ') + money.format(Math.abs(x)); }
  function dollars(x) { return (x < 0 ? '−' : '') + money.format(Math.abs(x)); }

  function fail(msg) {
    var error = document.getElementById('abError');
    error.hidden = false;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { set(id, '–'); });
    document.getElementById('abRebalance').innerHTML = '';
    document.getElementById('abGroups').innerHTML = '';
  }

  function update() {
    document.getElementById('abError').hidden = true;
    var cur = KEYS.map(function (k) { return num('abCur' + k); }),
        tgt = KEYS.map(function (k) { return num('abTgt' + k); }),
        ret = KEYS.map(function (k) { return num('abRet' + k); }),
        vol = KEYS.map(function (k) { return num('abVol' + k); });
    var rho = num('abCorr'), cash = num('abCash'), band = num('abBand');
    var sumT = sum(tgt.map(function (x) { return isNaN(x) ? 0 : x; }));
    set('abTargetSum', 'Target mix total: ' + (Math.round(sumT * 100) / 100) + '%');
    if (cur.concat(tgt, ret, vol, [rho, cash, band]).some(isNaN)) return fail('Fill in every box with a number (use 0 for none).');
    if (cur.some(function (x) { return x < 0; }) || cash < 0) return fail('Current values and new cash cannot be negative.');
    if (tgt.some(function (x) { return x < 0 || x > 100; })) return fail('Each target must be from 0% to 100%.');
    if (Math.abs(sumT - 100) > 0.01) return fail('The target mix adds up to ' + (Math.round(sumT * 100) / 100) + '%. Adjust it to total 100%.');
    if (ret.some(function (x) { return x < -50 || x > 50; })) return fail('Enter hypothetical returns from -50% to 50%.');
    if (vol.some(function (x) { return x < 0 || x > 100; })) return fail('Enter volatilities from 0% to 100%.');
    if (rho < 0 || rho > 1) return fail('Enter an average correlation from 0 to 1.');
    if (band < 0 || band > 50) return fail('Enter a tolerance band from 0 to 50 percentage points.');
    var total = sum(cur);
    if (total + cash <= 0) return fail('Enter at least one current value or some new cash to invest.');

    var r = ret.map(function (x) { return x / 100; }), s = vol.map(function (x) { return x / 100; });
    var wT = tgt.map(function (x) { return x / 100; });
    var tR = mixReturn(wT, r), tV = mixVol(wT, s, rho);
    set('abTotal', money.format(total));
    set('abTgtRet', pct(tR));
    set('abTgtVol', pct(tV));
    set('abTgtDiv', pct(weightedVol(wT, s) - tV) + ' lower');
    var base = total + cash;
    set('abRange1', dollars(base * (tR - tV)) + ' to ' + dollars(base * (tR + tV)));
    set('abRange2', dollars(base * (tR - 2 * tV)) + ' to ' + dollars(base * (tR + 2 * tV)));
    var wC = null;
    if (total > 0) {
      wC = cur.map(function (x) { return x / total; });
      var cV = mixVol(wC, s, rho);
      set('abCurRet', pct(mixReturn(wC, r)));
      set('abCurVol', pct(cV));
      set('abCurDiv', pct(weightedVol(wC, s) - cV) + ' lower');
    } else {
      ['abCurRet', 'abCurVol', 'abCurDiv'].forEach(function (id) { set(id, '–'); });
    }

    var t = trades(cur, wT, cash), moved = 0, off = 0;
    var rows = KEYS.map(function (k, i) {
      var curPct = wC ? wC[i] * 100 : 0, drift = curPct - tgt[i], outside = wC && Math.abs(drift) > band + 1e-9;
      if (t[i] < 0) moved += -t[i];
      if (outside) off++;
      return '<tr><th scope="row">' + NAMES[k] + '</th><td>' + money.format(cur[i]) + '</td><td>' +
        (wC ? curPct.toFixed(1) + '%' : '–') + '</td><td>' + tgt[i] + '%</td><td>' +
        (wC ? (drift > 0 ? '+' : drift < 0 ? '−' : '') + Math.abs(drift).toFixed(1) + ' pts' : '–') + '</td><td>' +
        money.format(wT[i] * base) + '</td><td>' + signed(t[i]) + '</td><td>' + (outside ? 'Outside band' : wC ? 'Within band' : '–') + '</td></tr>';
    });
    document.getElementById('abRebalance').innerHTML = rows.join('');
    set('abMoved', money.format(moved));
    set('abOffBand', wC ? String(off) + ' of ' + KEYS.length : '–');

    document.getElementById('abGroups').innerHTML = GROUP_ORDER.map(function (g) {
      var c = 0, tg = 0;
      KEYS.forEach(function (k, i) { if (GROUPS[k] === g) { c += cur[i]; tg += tgt[i]; } });
      return '<tr><th scope="row">' + g + '</th><td>' + money.format(c) + '</td><td>' +
        (total > 0 ? (c / total * 100).toFixed(1) + '%' : '–') + '</td><td>' + (Math.round(tg * 100) / 100) + '%</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('abForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
